/**
 * Local Lucide icon bundle (no runtime requests to api.iconify.design). The app renders icons through
 * src/components/wrappers/Icon.tsx with @iconify/react's OFFLINE build, which only knows the icons added from
 * src/assets/icons/lucide.json. That file is generated by `npm run icons` from @iconify-json/lucide: every string
 * literal in src/ that is a Lucide icon name is included (slightly over-inclusive by design, so icon names chosen at
 * runtime from string constants are covered too). src/assets/icons/lucide.test.ts fails when the file is stale.
 */
import { readdirSync, readFileSync } from 'node:fs'
import { join } from 'node:path'

type IconData = { body: string; width?: number; height?: number; left?: number; top?: number; hFlip?: boolean; vFlip?: boolean; rotate?: number }
type Alias = { parent: string } & Omit<IconData, 'body'>
/** Iconify's set metadata: who made the icons and under which licence (kept in the bundle as the licence notice). */
export type IconSetInfo = { name: string; author: { name: string; url?: string }; license: { title: string; spdx?: string; url?: string } }
export type IconSet = { prefix: string; info?: IconSetInfo; width?: number; height?: number; icons: Record<string, IconData>; aliases?: Record<string, Alias> }

const NAME = /^[a-z0-9]+(?:-[a-z0-9]+)*$/

function walk(dir: string): string[] {
  return readdirSync(dir, { withFileTypes: true }).flatMap((e) => (e.isDirectory() ? walk(join(dir, e.name)) : [join(dir, e.name)]))
}

/** Every quoted kebab-case string literal in the .ts/.tsx sources under `srcDir` (tests and the bundle itself excluded). */
export function candidateNames(srcDir: string): Set<string> {
  const out = new Set<string>()
  for (const f of walk(srcDir)) {
    if (!/\.tsx?$/.test(f) || /\.test\.tsx?$/.test(f)) continue
    for (const m of readFileSync(f, 'utf8').matchAll(/(["'`])([a-z0-9-]{1,48})\1/g)) if (NAME.test(m[2])) out.add(m[2])
  }
  return out
}

/** The subset of `full` holding `names` (aliases resolved to their parent icon), with stable key order. */
export function subset(full: IconSet, names: Iterable<string>): IconSet {
  const icons: Record<string, IconData> = {}
  const aliases: Record<string, Alias> = {}
  for (const n of [...new Set(names)].sort()) {
    if (full.icons[n]) icons[n] = full.icons[n]
    else if (full.aliases?.[n]) {
      aliases[n] = full.aliases[n]
      let p = full.aliases[n].parent
      while (!full.icons[p] && full.aliases?.[p]) {
        aliases[p] = full.aliases[p]
        p = full.aliases[p].parent
      }
      if (full.icons[p]) icons[p] = full.icons[p]
    }
  }
  const sorted = <T,>(o: Record<string, T>) => Object.fromEntries(Object.entries(o).sort(([a], [b]) => a.localeCompare(b)))
  return { prefix: full.prefix, ...(full.info ? { info: full.info } : {}), width: full.width, height: full.height, icons: sorted(icons), ...(Object.keys(aliases).length ? { aliases: sorted(aliases) } : {}) }
}

export function loadLucide(root: string): IconSet {
  const dir = join(root, 'node_modules/@iconify-json/lucide')
  const set = JSON.parse(readFileSync(join(dir, 'icons.json'), 'utf8')) as IconSet
  const meta = JSON.parse(readFileSync(join(dir, 'info.json'), 'utf8')) as IconSetInfo
  // Only the attribution fields: name, author and licence (no sample lists or counts that change between releases).
  return { ...set, info: { name: meta.name, author: meta.author, license: meta.license } }
}

export function buildBundle(root: string): string {
  return `${JSON.stringify(subset(loadLucide(root), candidateNames(join(root, 'src'))), null, 1)}\n`
}
